# Rebuild the evidence register from active calibration and explicit judgments.
# Offline. Run from any directory using Rscript; no source refresh or deployment.
args<-commandArgs(FALSE);script<-sub('^--file=','',args[grepl('^--file=',args)][1])
setwd(normalizePath(file.path(dirname(script),'..'),mustWork=TRUE))
source('R/model.R');x<-load_inputs();cal<-calibrate(x);a<-default_assumptions()
rows<-list()
add<-function(domain,item,classification,value_rule,source,source_url='',model_addition='',limitation='') {
  rows[[length(rows)+1L]]<<-data.frame(domain,item,classification,value_rule,source,source_url,model_addition,limitation)
}
igr<-'https://treasury.gov.au/publication/2026-intergenerational-report'
pbo<-'https://www.pbo.gov.au/publications-and-data/publications/2026-27-National-Fiscal-Outlook'
abs<-'https://www.abs.gov.au/statistics/economy/government/government-finance-statistics-annual/2024-25'
tax<-'https://www.abs.gov.au/statistics/economy/government/taxation-revenue-australia/2024-25'
ato<-'https://data.gov.au/data/dataset/faea4485-f407-457d-97f8-3f0822ccd654'
add('Anchor','2030 fiscal totals and stocks','Sourced',sprintf('AUD bn: revenue %.3f; expenses %.3f; interest %.3f; net capital investment %.3f; gross debt %.3f; net debt %.3f',cal$official$revenue_billion_dollars,cal$official$expenses_billion_dollars,cal$official$public_debt_interest_billion_dollars,cal$nci0,cal$gross_debt0,cal$official$net_debt_billion_dollars),'PBO 2026-27 NFO; Tables 1 and 2',pbo,'Use consolidated national series directly','Source forecast to 2030; later model outcomes are not PBO forecasts')
add('Anchor','2030 nominal GDP','Identity','Gross debt dollars divided by published gross-debt/GDP ratio','PBO NFO Tables 1 and 2',pbo,'Infer a consistent denominator','Published ratios are rounded')
add('Anchor','2030 programme allocations','Calibrated','2025 functional spending projected to 2030, then one common factor matches PBO primary expenses','ABS GFS + programme outlays + PBO',abs,'Allocation growth uses 2.5% prices, 1.2% productivity, 0.3% relative prices and programme assumptions','Individual programme anchors are our allocations, not official forecasts')
add('Anchor','2030 revenue-head allocations','Calibrated','2025 observed receipts uprated and reconciled pro rata to PBO revenue','ABS GFS/Taxation + ATO + PBO',tax,'Non-PIT bridge uses (1.025*1.012)^5; PIT uses uprated percentiles and schedule','Bridge omits an explicit population-growth factor; not independently forecast normal tax shares')
add('Anchor','Tax consolidation','Calibrated','Detailed ABS tax heads scaled pro rata to observed national GFS tax total','ABS Taxation Revenue and GFS 2024-25',tax,'Absorb revisions and consolidation difference','GST collected once; adjustment does not identify each eliminated payment')
add('Macro','Selected economic defaults','User choice','Productivity 1.2%; NGDP/person 3.2%; population 1.2%; average hours 0%','User scenario preferences and prototype default','','Independent controls from shared 2030 anchor','Productivity 1.2% is the retained prototype reference, not an estimated forecast')
add('Macro','Nominal and real output','Identity','GDP = anchor * population index * nominal GDP/person index; real output = hours index * productivity index','Model accounting structure','','Prices reconcile nominal GDP to real output and ToT income factor','Single domestic price index proxies CPI, wages and programme deflation')
add('Macro','ToT transmission','Judgment','Income factor = ToT^0.20; level change phases in over 10 years','Prototype scenario design; no estimated coefficient','','Domestic prices = GDP index / (real output index * income factor)','Neither 0.20 nor the 10-year phase-in is externally calibrated')
add('Demography','Population age/sex shares','Sourced + proxy','IGR C8.6 ages at 2025/2036/2066; C8.1 growth; C8.2 initial level; Centre for Population sex ratios','2026 IGR chart workbooks; 2025 Population Statement',igr,'Linear annual interpolation; scale all age/sex cells uniformly for selected total growth','Migration and fertility responses are not modelled')
add('Demography','Participation and employment','Sourced + proxy','ABS April 2025-March 2026 age/sex rates; IGR C9.13 sex-specific participation targets','ABS Labour Force Detailed March 2026; IGR',igr,'Common odds shift matches targets; hold age/sex unemployment rates fixed','A bridge to official targets, not an independently estimated cohort model')
add('Demography','Hours','Sourced + user choice','Observed ABS age/sex hours; -0.1% aggregate source trend before scenario anchor; constant hours thereafter by default','ABS EM1a March 2026; IGR C7.2; user preference',igr,'2030 starting average then selected annual hours growth','Source trend is not the active post-2030 default')
add('Revenue','Personal income tax','Sourced + judgment','ATO 100 percentile cells; resident schedule and LITO; taxpayers scale with employment; Wage-indexed thresholds by default','ATO 2023-24 Table 16A; resident schedule; user indexation preference',ato,'2024 income cells uprated six years at 1.025*1.012; calibrate to revenue anchor','Fixed distribution shape; excludes many deductions/offsets, CGT realisations and individual behaviour; Wage indexation is a user-selected scenario policy')
add('Revenue','Company tax','Calibrated + judgment',sprintf('Anchor %.6f%% GDP * ToT^eta; eta=1',100*cal$revenue_anchor['company']/cal$gdp0),'ABS/PBO calibrated allocation; user requested structural ToT link',tax,'eta=1 is an illustrative judgment; slider 0-2','Anchor is not a directly published structural profit-tax share; no loss-offset or firm model')
add('Revenue','GST','Proxy','Anchor * nominal GDP index; constant consumption/GDP, taxable share and effective yield','ABS observed level; IGR A3.3 supports consumption-base method',igr,'Consumption/GDP and coverage held fixed without estimating their levels','Does not model ageing-related consumption composition or exemptions separately')
add('Revenue','Payroll tax','Proxy','Anchor * employed index * nominal earnings index; fixed effective coverage/yield','ABS observed level; wage-bill tax-base logic',tax,'Proportional taxable wage-bill proxy replaces historical elasticity','No employer-size distribution, state thresholds, indexation or jurisdiction split')
add('Revenue','Medicare levy and FBT','Proxy','Combined observed anchor * nominal wage-bill index','ABS separate source lines combined by model',tax,'Constant effective yield on remuneration proxy','Still combined; levy thresholds and taxable fringe benefits need separate models')
add('Revenue','Superannuation tax','Proxy','Total observed super tax anchor * nominal wage-bill index','ABS income tax paid by superannuation funds',tax,'Transitional aggregate proxy only','Contributions and earnings taxes remain combined; private return slider does NOT affect this head; needs taxable fund-assets model')
add('Revenue','Excises and customs','Proxy + judgment','Anchor * population index * domestic price index','ABS aggregate observed level; unit-tax logic; IGR A3.3 structural-excise discussion',igr,'Assume constant taxable units per resident and CPI-indexed effective unit rates','Aggregate approximation: customs includes ad valorem taxes; no fuel/tobacco/alcohol split, EV transition or consumption erosion fitted')
add('Revenue','Property taxes','Proxy','Anchor * GDP index: constant property-value/GDP ratio and effective yield','ABS observed level; property-base logic',tax,'Property values proxied by nominal GDP','Includes a mix of property taxes/rates; no land valuations, thresholds or local rate-setting model')
add('Revenue','Stamp duties','Proxy','Anchor * GDP index: constant property-value/GDP ratio, turnover and effective yield','ABS financial/capital transactions aggregate',tax,'Property-transactions interpretation used as a broad proxy','Not all transactions are property; no separate price, turnover or progressive schedule model')
add('Revenue','Other taxes','Proxy','Anchor * nominal GDP index','ABS residual reconciled to consolidated GFS',tax,'Constant residual tax/GDP ratio','Heterogeneous taxes; no claim of a separately estimated structural base')
add('Revenue','Royalties','Judgment','Anchor * domestic nominal output index * ToT^2','ABS observed royalty income',abs,'ToT exponent 2 is an illustrative scenario assumption','Because domestic prices adjust, net share response is ToT^(2-0.20); no resource-volume or jurisdiction model')
add('Revenue','Fees and other receipts','Proxy','Anchor * domestic nominal output index','ABS GFS residual after taxes, royalties and interest',abs,'Constant effective yield on domestic output proxy','Includes dividends; no separate public-corporation earnings model')
add('Revenue','Historical elasticities','Descriptive only','2017-2025 annual tax/GDP growth regressions, shrunk toward one','ABS tax history + PBO GDP; model estimates',tax,'Retained for provenance; none enter any projection','Short sample mixes policy, cycles and composition; not structural scenario responses')
add('Spending','Common programme equation','Identity','Spending = anchor * population * age/cohort * coverage * domestic prices * real unit cost * relative-price factor * intensity * policy rule * aggregate cost scaling','Model accounting structure','','Health/education unit costs use input baskets or funding proxies; other services retain productivity exponents','Identity follows from chosen structure; it does not establish correct parameter values')
pp<-cal$programmes
exposure<-c('Health'='Separate C12.10 hospital/medical/pharmaceutical weights; residual health total population; sum five subfunctions',
 'Education'='Schools ages 5-17, higher education 18-24, VET 15-64, other total population; higher/VET allocation uses a cross-source proxy',
 'Age Pension'='Population aged 67+; synthetic entitlement/coverage model',
 'Aged care'='Absolute IGR C6.6 aged-care age weights',
 'NDIS'='NDIA D.13 incidence below 65; retain older participants using population survival',
 'Other social protection'='Population aged 15-66',
 'Other public services'='Seven GFS functions, each with total-population demand','Defence'='Explicit GDP-share target, not exposure equation')
for(i in seq_len(nrow(pp))) {
 q<-pp[i,];n<-q$programme
 if(n%in%c('Health','Education')){
   add('Spending',n,'Sourced + proxy + judgment',sprintf('2025 allocation $%.4fbn; 2030 anchor $%.4fbn; distinct subfunction cost rules; aggregate annual adjustment 0%%',q$base_2025_bn,q$anchor_2030_bn),
     'ABS/AIHW allocation; IHACPA hospital costs; ACARA school costs; university Finance 2024; National Skills Agreement',
     if(n=='Health')'https://www.ihacpa.gov.au/resources/national-hospital-cost-data-collection-public-sector-2023-24' else 'https://www.education.gov.au/higher-education-statistics',
     paste(exposure[n],'; see health_education_parameters.csv for nine source/assumption blocks; cost adjustment multiplies all unit costs by (1+adjustment)^years'),
     'Observed input shares are scope proxies, not causal elasticities; fixed coverage/service productivity; health intensity 0.5% retained, not fitted; medicines CPI-only is a judgment')
   next
 }
 add('Spending',n,'Calibrated + judgment',sprintf('2025 allocation $%.4fbn; calibrated 2030 $%.4fbn; productivity pass-through %.0f%%; intensity %.2f%%/year',q$base_2025_bn,q$anchor_2030_bn,100*q$wage_pass_through,100*q$excess_cost_growth),
   if(n=='NDIS')'NDIA 2024-25 Note 1.1G and Q4 D.13' else if(n=='Age Pension')'ANAO outlay; Services Australia/DSS rules' else 'ABS GFS 2024-25; IGR age profiles where applicable',
   if(n=='NDIS')'https://www.ndis.gov.au/media/8108/download' else if(n=='Age Pension')'https://www.anao.gov.au/work/performance-audit/administration-of-the-age-pension' else if(n%in%c('Health','Education','Aged care'))igr else abs,
   paste(exposure[n],'; pass-through and intensity coefficients are model judgments. Four pass-through rates and two aggregate cost adjustments are adjustable without recalibrating 2030; standards policy overrides social protection to 100%.'),
   if(n=='Defence')'2.5% GDP by 2035 is a prototype target judgment; not a sourced national defence forecast. Listed cost parameters do not drive this target.' else if(n=='Age Pension')'Generic pass-through/intensity fields are overridden by the pension module; wealth assumptions matter.' else 'Common 0.3% relative service-price growth also applies; programme-specific service productivity is not separately identified')
}
add('Spending','Relative service prices','Judgment','0.3% annual excess service-price growth, separate from input costs and intensity','Prototype scenario assumption','','Service/mixed programmes; excluded from medicine CPI proxy and VET funding proxy','Potential overlap with intensity and wage costs; coefficients not jointly estimated')
add('Spending','Health/education/care age weights','Sourced + proxy','Hospital/medical/pharmaceutical C12.10 shapes; residual health population; care C6.6; schools 5-17, higher education 18-24, VET 15-64, other education population','2026 IGR; ABS Education; RoGS VET scope',igr,'Sum 24 subfunctions to categories; health shapes and education age bands are proxies; see README and background PDF','No separately estimated enrolment or residential/home uptake; historical category bridge retains prior profiles')
add('Spending','NDIS starting expenditure and demand','Sourced + proxy','2025 plan expenses $46.352178bn; age participation from Q4 D.13','NDIA Annual Report Note 1.1G; Q4 2024-25 D.13','https://www.ndis.gov.au/media/7891/download','No new entrants at 65+; existing cohorts age forward; intensity default 0.5%','No independent disability severity/eligibility forecast or fitted official total growth; administration remains in residual')
add('Spending','Aged care starting expenditure','Sourced','2025 all-government expenditure $39.8bn','AIHW GEN 28 August 2026','https://www.gen-agedcaredata.gov.au/topics/spending-on-aged-care','Subtract from Social Protection before residual allocation','Not a separate forecast of future residential/home-care utilisation')
add('Spending','Age Pension starting expenditure','Sourced + proxy','2025 outlay $62.2bn','ANAO Administration of the Age Pension','https://www.anao.gov.au/work/performance-audit/administration-of-the-age-pension','Cash outlay used as a GFS allocation approximation','Cash and GFS expense concepts differ')
add('Pension','Starting status proportions','Sourced + calibration','2026 IGR C12.19 full/assets-tested/income-tested/no-pension mix','2026 IGR C12.19',igr,'Synthetic wealth archetypes reproduce category mix; each group weighted across age/tenure/family status','Not observed household wealth; no claim to reproduce Treasury pension microsimulation')
add('Pension','Synthetic households and assets','Judgment','65% couple; 75% homeowner; 80% financial assets; archetype assets 0.3*free, free+half cutoff, or 1.15*cutoff','Prototype construction; no external estimate','','Income-tested archetype solved for half-rate pension; weights age-invariant','These guesses materially affect pension sensitivity and need replacement with household data')
add('Pension','Super accumulation and drawdown','User choice + judgment','4% real private return (user); slider to 7%; 5% annual drawdown; 12% SG and 15% contributions tax','User return preference; ATO SG/tax; stylised drawdown','https://www.ato.gov.au/tax-rates-and-codes/key-superannuation-rates-and-thresholds/super-guarantee','Synthetic extra contribution years; midpoint productivity uplift; no contribution caps','5% is not the age-specific statutory drawdown schedule; no tax-on-earnings or public-asset return channel')
add('Pension','Indexation and standards policy','Judgment','Pre-anchor 2.5% prices and 1.2% productivity; post-anchor thresholds follow prices and maximum pension uses max price/earnings index','Simplified implementation of pension rules; prototype bridge','','Standards case scales starting entitlements with wage/price index, preserving coverage','Not exact statutory review timing or all indexation benchmarks; hours affect earnings proxy')
for(i in seq_len(nrow(x$policy))) {
 q<-x$policy[i,]
 if(q$parameter%in%c('super_real_return','retirement_drawdown','ndis_plan_expenses_2025','aged_care_expenses_2025','age_pension_expenses_2025'))next
 add('Policy parameter',q$parameter,'Sourced',paste(q$value,q$unit),q$status,q$source_url,'Transcribed into data/policy_parameters.csv','Simplified application in representative pension/tax model; source parameter does not validate synthetic households')
}
add('Financing','Gross/net debt and fiscal balance','Identity','Net debt = gross debt - modelled financial assets; net debt change = -fiscal balance','Model stock-flow accounting','','Financial-asset acquisition financed explicitly','Excludes valuation effects and wider balance-sheet liabilities')
add('Financing','Borrowing rate','Calibrated + judgment','2030 PBO interest / 2029 gross debt, converges to 4.4% nominal by 2040','PBO anchor plus prototype long-run assumption',pbo,'4.4% and convergence horizon are judgments; user can vary rate','No automatic inflation response, term structure or maturity/refinancing model')
add('Financing','Asset income and accumulation','Calibrated + judgment','Yield = calibrated anchor interest receipts / anchor financial assets; maintain real assets per person; invest surplus after gross debt repaid','PBO gross-minus-net debt and ABS interest receipts',abs,'Opening asset stock earns constant calibrated yield','Gross-minus-net debt is an accounting proxy for earning assets; excludes revaluations and heterogeneous assets')
add('Financing','Net capital investment','Judgment','2030 anchor * population index * domestic price index * productivity index^0.5','PBO anchor; prototype investment rule',pbo,'0.5 productivity exponent is an unestimated scenario assumption','No asset-class investment, depreciation or infrastructure-demand model')
register<-do.call(rbind,rows)
revenue_names<-c('Personal income tax'='personal_income','Company tax'='company','GST'='gst',
 'Payroll tax'='payroll','Medicare levy and FBT'='medicare_fbt','Superannuation tax'='superannuation',
 'Excises and customs'='excises_customs','Property taxes'='property','Stamp duties'='stamp_duties',
 'Other taxes'='other_taxes','Royalties'='royalties','Fees and other receipts'='fees_other')
for(n in names(revenue_names)) {
 k<-which(register$domain=='Revenue' & register$item==n);key<-revenue_names[n]
 register$value_rule[k]<-paste0(sprintf('2025 observed/reconciled $%.4fbn; calibrated 2030 $%.4fbn. ',cal$revenue_observed_2025[key],cal$revenue_anchor[key]),register$value_rule[k])
}
write.csv(register,'data/assumption_register.csv',row.names=FALSE,na='')
cat('Wrote',nrow(register),'evidence and assumption register entries.\n')
